#include<bits/stdc++.h>
using namespace std;
class SoPhuc{
	private:
		double thuc;
		double ao;
	public:
		SoPhuc(){
			this->thuc = 0;
			this->ao = 0;
		}
		SoPhuc operator + (SoPhuc sp){
			SoPhuc t;
			t.thuc = thuc + sp.thuc;
			t.ao = ao + sp.ao;
			return t;
		}
		bool operator == (const SoPhuc*sp) const{
			return thuc == sp.thuc && ao == sp.ao;
		}
		friend istream &operator >> (istream &is, SoPhuc &sp){
			cout<<"Nhap phan thuc va ao: ";
			is>>sp.thuc>>sp.ao;
			return is;
		}
		friend ostream &operator << (ostream &os, SoPhuc &sp){
			os<<sp.thuc<<sp.ao;
			return os;
		}
};
int main(){
	SoPhuc *sp1 = new SoPhuc();
	cin>>*sp1;
	cout<<*sp1;
	SoPhuc *sp2 = new SoPhuc();
	cin>>*sp2;
	cout<<*sp2;
	SoPhuc sp3 = *sp1 + *sp2;
	cout<<sp3;
	if(*sp1 == *sp2){
		cout<<"Bang nhau"<<endl;
	}else{
		cout<<"Khong bang nhau"<<endl;
	}
	return 0;
}
